        "id": 3,
        "image": "images/districts/narsingdi/hist-3.webp",
        "name": "Ashrafpur Mosque",
        "nameEn": "Ashrafpur Mosque",
        "nameBn": "আশরাফপুর মসজিদ",
        "category": "Medieval Archaeological Site",
