        "id": 2,
        "image": "images/districts/cumilla/tour-2.webp",
        "name": "Lalmai Hills",
        "nameEn": "Lalmai Hills",
        "nameBn": "লালমাই পাহাড়",
        "category": "Geological Red-Clay Ridge",
